def require(condition,message):
    if not condition:raise AssertionError(message)

def digest(path):
    value=hashlib.sha256()
    with path.open('rb') as stream:
        for part in iter(lambda:stream.read(1024*1024),b''):value.update(part)
    return value.hexdigest()

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,*args,**kwargs):return None

def api_get(path):
    request=urllib.request.Request('https://api.github.com/repos/ATLKR/OpenGeul'+path,
        headers={'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'})
    request.add_unredirected_header('Authorization','Bearer '+os.environ['GH_TOKEN'])
    with urllib.request.build_opener(NoRedirect()).open(request,timeout=20) as response:
        raw=response.read(2*1024*1024+1)
    require(len(raw)<=2*1024*1024,'Official API response exceeds its bound')
    return json.loads(raw),hashlib.sha256(raw).hexdigest()

def prepare_runtime(work,report):
    release,release_sha=api_get('/releases/'+str(RELEASE_ID))
    run,run_sha=api_get('/actions/runs/'+str(PRODUCER_RUN))
    tag,tag_sha=api_get('/git/ref/tags/v1.1.3')
    require(release['id']==RELEASE_ID and release['tag_name']=='v1.1.3'
        and release['target_commitish']==PRODUCER_HEAD and release['draft'] is False
        and release['prerelease'] is False and len(release['assets'])==22,
        'Immutable formal producer release identity changed')
    require(run['id']==PRODUCER_RUN and run['run_attempt']==1 and run['head_sha']==PRODUCER_HEAD
        and run['head_branch']=='v1.1.3' and run['event']=='push'
        and run['status']=='completed' and run['conclusion']=='success','Source87 producer run is not successful')
    require(tag['object']['type']=='commit' and tag['object']['sha']==PRODUCER_HEAD,
        'Immutable producer tag identity changed')
    report['producer']={'head':PRODUCER_HEAD,'runId':PRODUCER_RUN,'attempt':1,
        'tag':'v1.1.3','releaseId':RELEASE_ID,'releaseAPIsha256':release_sha,
        'runAPIsha256':run_sha,'tagAPIsha256':tag_sha}
    package=work/'package';package.mkdir()
    for name,(asset_id,size,sha) in ASSETS.items():
        matches=[a for a in release['assets'] if a['name']==name]
        require(len(matches)==1,'Producer asset is not unique');asset=matches[0]
        require(asset['id']==asset_id and asset['size']==size and asset['digest']=='sha256:'+sha,
            'Producer asset ID, bytes or server digest changed')
        target=package/name
        with target.open('xb') as output:
            result=subprocess.run(['gh','api',f'repos/ATLKR/OpenGeul/releases/assets/{asset_id}',
                '-H','Accept: application/octet-stream'],stdout=output,stderr=subprocess.DEVNULL,timeout=90)
        require(result.returncode==0,'Public producer asset transport failed')
        require(target.stat().st_size==size and digest(target)==sha,'Downloaded producer bytes changed')
    provenance=json.loads((package/f'provenance-{ARCH}.json').read_bytes())
    require(provenance['repository']=='ATLKR/OpenGeul' and provenance['commit']==PRODUCER_HEAD
        and provenance['runId']==str(PRODUCER_RUN) and provenance['architecture']==ARCH
        and provenance['version']=='1.1.3','Producer provenance changed')
    # This manifest belongs to a diagnostic subset, not to formal Source22.
    # The existing complete portable/MSIX byte-parity validator remains intact.
    subset=work/'verified-package-subset';subset.mkdir()
    names=[n for n in ASSETS if n.endswith(('.zip','.msix'))]
    for name in names:shutil.copyfile(package/name,subset/name)
    (subset/'SHA256SUMS.txt').write_text(''.join(ASSETS[n][2]+'  '+n+'\n' for n in sorted(names)),encoding='utf8')
    from prepare_payload import prepare
    runtime=work/'runtime';prepare(subset,runtime,ARCH)
    require(digest(runtime/'OpenGeul.exe')==EDITOR_SHA and digest(runtime/'Tools/rhwp.exe')==CLI_SHA,
        'Producer runtime binary changed')
    report['producer'].update(editorSha256=EDITOR_SHA,cliSha256=CLI_SHA)
    return runtime

def bind_diagnostic_context(env):
    # Validate the REAL event/ref/job/workflow tuple with the unchanged helper.
    # This is not a Source or Store producer identity and no environment is set.
    spec=importlib.util.spec_from_file_location('native_hit_runner_ready',ROOT/'e2e/runner-ready.py')
    ready=importlib.util.module_from_spec(spec);spec.loader.exec_module(ready)
    scope=ready.binding(env)
    require(scope['context']=='diagnostic','Diagnostic readiness context changed')
    return scope


def read(path,cap=JSON_CAP):
    path=Path(path)
    for parent in (path,*path.parents):
        info=parent.lstat()
        require(not stat.S_ISLNK(info.st_mode) and not getattr(info,'st_file_attributes',0)&0x400,'진단 파일 링크/reparse 금지')
    require(path.is_file() and 0<path.stat().st_size<=cap,'진단 파일 상한/형식')
    raw=path.read_bytes();require(0<len(raw)<=cap,'진단 읽기 상한');return raw

def read_json(path):
    def pairs(items):
        out={}
        for k,v in items:require(k not in out,'중복 JSON 키');out[k]=v
        return out
    return json.loads(read(path),object_pairs_hook=pairs,parse_constant=lambda _:(_ for _ in ()).throw(ValueError('비정규 JSON 숫자')))

def prepare_inputs():
    raw=base64.b64decode(BUNDLE_B64,validate=True)
    require(len(raw)<128*1024 and hashlib.sha256(raw).hexdigest()==BUNDLE_SHA,'고정 합성 입력 ZIP 불일치')
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        require(len(z.infolist())==len(INPUTS) and set(z.namelist())==set(INPUTS) and z.testzip() is None,'입력 ZIP 이름/CRC 불일치')
        for info in z.infolist():
            require(not info.is_dir() and not stat.S_ISLNK(info.external_attr>>16),'입력 ZIP 특수파일 금지')
            expected=INPUTS[info.filename];data=z.read(info)
            require(len(data)==expected['bytes'] and hashlib.sha256(data).hexdigest()==expected['sha256'],'고정 입력 SHA 불일치')
            target=ROOT/info.filename;target.parent.mkdir(parents=True,exist_ok=True)
            with target.open('xb') as stream:stream.write(data)

def contracts():
    for name,sha in CONTRACTS.items():require(digest(ROOT/name)==sha,'검증한 인쇄 helper/기준 바이트 변경')

def collect(report):
    from print_results import completed_job
    from print_raster import load_reference,match_reference
    require(digest(ROOT/'.work/physical-print/runtime/OpenGeul.exe')==EDITOR_SHA and digest(ROOT/'.work/physical-print/runtime/Tools/rhwp.exe')==CLI_SHA,'실행 후 Source87 런타임 binary 변경')
    source=ROOT/'print-evidence';summary=read_json(source/'summary.json');junit=read(source/'junit.xml')
    require(all(type(summary.get(k)) is int for k in ('tests','failures','skipped'))
        and (summary.get('tests'),summary.get('failures'),summary.get('skipped'))==(8,0,0),'진단 인쇄8건 전체 성공 필요')
    rows=summary.get('results');require(type(rows) is list and len(rows)==8 and {r.get('name') for r in rows}==set(CASES) and all(r.get('passed') is True for r in rows),'8건 실제 결과 불일치')
    xml=ET.fromstring(junit);require(xml.tag=='testsuite' and xml.attrib=={'name':'virtual-print','tests':'8','failures':'0','skipped':'0'} and len(xml)==8 and {r.attrib.get('name') for r in xml}==set(CASES) and all(r.tag=='testcase' and len(r)==0 for r in xml),'진단 JUnit8건 불일치')
    fixture_paths={'table--300':'print-fixtures/print-table--300.hwpx','table-0':'print-fixtures/print-table-0.hwpx','table-600':'print-fixtures/print-table-600.hwpx','multipage':'print-fixtures/print-multipage.hwpx','page-range':'print-fixtures/print-multipage.hwpx','basic-hwp':'inputs/e2e-fixtures/basic.hwp','basic-hwpx':'inputs/e2e-fixtures/basic.hwpx','cancel':'inputs/e2e-fixtures/basic.hwpx'}
    used=0;pdfs=[];case_records=[]
    for case in CASES:
        folder=source/case;runtime=read_json(folder/'session/runtime.json');preserved=read_json(folder/'source-preservation.json');result=read_json(folder/'result.json')
        fixture=ROOT/fixture_paths[case];fixture_sha=INPUTS[fixture_paths[case]]['sha256']
        require(digest(fixture)==fixture_sha and digest(folder/fixture.name)==fixture_sha,'실제 사례 입력 원본 변경')
        require(preserved.get('unchanged') is True and preserved.get('before')==preserved.get('after')==runtime.get('fixtureSha256')==result.get('sourceSha256')==fixture_sha,'사례 원본 보존 불일치')
        native=runtime.get('nativeArchitecture',{});machine=0xaa64 if ARCH=='arm64' else 0x8664
        require((native.get('sourceCommit'),native.get('sourceRun'),native.get('runAttempt'))==(report['controller']['sourceCommit'],report['controller']['runId'],report['controller']['runAttempt']),'실제 controller 실행context 불일치')
        require(all(type(native.get(k)) is int for k in ('processMachine','peMachine','nativeMachine','processId'))
            and (native.get('architecture'),native.get('processMachine'),native.get('peMachine'),native.get('nativeMachine'))==(ARCH,0,machine,machine)
            and native.get('native') is True and native.get('runningAtInspection') is True,'실제 앱 native 아키텍처 불일치')
        require(native.get('sha256')==runtime.get('executableSha256')==EDITOR_SHA and native.get('helperSha256')==CONTRACTS['e2e/native_architecture.py'] and native.get('bytes')==(ROOT/'.work/physical-print/runtime/OpenGeul.exe').stat().st_size,'실제 Source87 binary SHA 불일치')
        require(Path(native['imagePath']).resolve()==(ROOT/'.work/physical-print/runtime/OpenGeul.exe').resolve() and runtime.get('mode')=='native','실제 producer 실행경로 불일치')
        guard_path=folder/'print-native-preferences-diagnostic.json';guard=read_json(guard_path)
        require(guard.get('passed') is True and guard.get('operation')=='native-preferences-input' and guard.get('sourceQualified') is False,'실제 Preferences guard 통과 원본 필요')
        require(type(native.get('processId')) is int and native['processId']>0
            and all(type(guard.get(k)) is int and guard[k]>0 for k in ('appPid','dialogHwnd','dialogPid','dialogTid','buttonHwnd','buttonTid','hitHwnd'))
            and guard['appPid']==native['processId'] and guard.get('foregroundAtInput')==guard['dialogHwnd'],
            '실제 Preferences PID/HWND/전송 직전 전경 바인딩 불일치')
        fallback=guard.get('hitHwnd')!=guard.get('buttonHwnd')
        if fallback:require(type(guard.get('groupboxStyle')) is int and guard['groupboxStyle']&0xF==7 and guard.get('resolvedButtonHwnd')==guard.get('buttonHwnd') and type(guard.get('buttonParentHwnd')) is int and guard['buttonParentHwnd']>0,'실제 BS_GROUPBOX/정확 버튼 경로 불일치')
        record={'case':case,'fixtureSha256':fixture_sha,'runtimeSha256':digest(folder/'session/runtime.json'),'preservationSha256':digest(folder/'source-preservation.json'),'resultSha256':digest(folder/'result.json'),'preferencesGuardSha256':digest(guard_path),'preferencesGuardOriginal':case+'/print-native-preferences-diagnostic.json','preferencesPath':'native-groupbox7' if fallback else 'direct-exact-hit','groupboxStyle':guard.get('groupboxStyle'),'controllerContextIsNotBinaryProducer':True}
        if case=='cancel':
            require(not (folder/'printed.pdf').exists() and not (folder/'printed.pdf').is_symlink()
                and not (folder/'print-save-input-diagnostic.json').exists()
                and result.get('cancelled') is True and result.get('jobs')==[],'취소에서 Save 입력/PDF/스풀 생성 금지')
            record['cancelledWithoutPdfOrJob']=True
        else:
            save_path=folder/'print-save-input-diagnostic.json';save=read_json(save_path)
            require(save.get('operation')=='native-save-input' and save.get('phase')=='save-dispatched'
                and save.get('passed') is True and save.get('pathAccepted') is True
                and save.get('sourceQualified') is False,'실제 owned Save guard 통과 원본 필요')
            require(all(type(save.get(k)) is int and save[k]>0 for k in
                ('appPid','dialogHwnd','dialogPid','dialogTid','fieldHwnd','buttonHwnd','buttonTid','hitHwnd','hitHwndAtInput'))
                and save['appPid']==native['processId'] and save['hitHwnd']==save['hitHwndAtInput']==save['buttonHwnd']
                and save.get('foregroundAtInput')==save['dialogHwnd'],'실제 Save 전경/두 전역 hit 바인딩 불일치')
            owned={native['processId']:native,**{r['processId']:r for r in runtime['webview2Native']['processes']}}
            require(runtime['webview2Native'].get('rootProcessId')==native['processId']
                and len(owned)==len(runtime['webview2Native']['processes'])+1,'실제 Save WebView 원본 소유 inventory 불일치')
            current=save['dialogPid'];seen=set()
            while current!=native['processId']:
                require(current not in seen and current in owned,'실제 Save WebView 소유 경로 불일치')
                seen.add(current);current=owned[current]['parentProcessId']
            processes=save.get('processes');identities=save.get('runtimeIdentities')
            require(type(processes) is list and type(identities) is list
                and len({p.get('pid') for p in processes})==len(processes)
                and len({p.get('pid') for p in identities})==len(identities)
                and {native['processId'],save['dialogPid']}<=set(p.get('pid') for p in processes),
                '실제 Save held-process 기록 누락')
            for process in processes:
                require(process.get('pid') in owned and type(process.get('creation')) is int and process['creation']>0
                    and type(process.get('session')) is int and process['session']>=0,'실제 Save process 생성/세션 기록 불일치')
                if process['pid']!=native['processId']:
                    require(process.get('parentProcessId')==owned[process['pid']]['parentProcessId'],'실제 Save held WebView 부모 불일치')
            require({native['processId'],save['dialogPid']}<=set(p.get('pid') for p in identities),'실제 Save binary 기록 누락')
            for identity in identities:
                require(identity.get('pid') in owned and all(identity.get(k)==owned[identity['pid']].get(k)
                    for k in ('sha256','bytes','peMachine','processMachine','nativeMachine')),'실제 Save process binary 불일치')
            progress_path=folder/'print-output-progress-diagnostic.json';progress=read_json(progress_path)
            require(progress.get('phase')=='owned-spooler-completed' and progress.get('passed') is True
                and type(progress.get('timeoutSeconds')) is int and progress['timeoutSeconds']==30,
                '원래 owned spooler 완료 단계 성공 필요')
            record.update(saveGuardSha256=digest(save_path),saveGuardOriginal=case+'/print-save-input-diagnostic.json',
                          outputProgressSha256=digest(progress_path),ownedSaveDialogPid=save['dialogPid'])
            pages=2 if case=='multipage' else 1;pdf=read(folder/'printed.pdf',LIMIT);inspection=read_json(folder/'pdf-check/inspection.json');spool=read_json(folder/'spooler.json')
            sha=hashlib.sha256(pdf).hexdigest();checks=inspection.get('checks')
            require(pdf.startswith(b'%PDF-') and pdf.rstrip().endswith(b'%%EOF') and inspection.get('sha256')==result.get('sha256')==sha,'완성 PDF 원본 SHA 불일치')
            require(inspection.get('mode')==result.get('mode')=='reviewed-raster-fingerprint' and type(checks) is list and len(checks)==pages and [r.get('page') for r in checks]==list(range(1,pages+1)) and result.get('checks')==checks,'원래 PDF 전체 페이지 검사 불일치')
            book,refs=load_reference(case)
            require(inspection.get('referenceRun')==book['sourceRun'] and inspection.get('referenceCommit')==book['productCommit'],'원래 PDF 기준 출처 불일치')
            for i,check in enumerate(checks):
                actual={k:check[k] for k in ('pixels','ink','bbox','maskSha256')}
                require(check['referenceId']==match_reference(actual,refs[i],book,case,i+1),'원래 reviewed mask/variant 불일치')
                size=check.get('size_pt');require(type(size) is list and len(size)==2 and all(type(v) in (int,float) and abs(v-w)<=1 for v,w in zip(size,(595.28,841.86))),'원래 A4 geometry 불일치')
            require(all(result.get(k)==spool.get(k) for k in ('queue','jobs','jobMedia')),'원래 스풀 원본 결과 불일치')
            require(completed_job(spool['jobs'],spool['queue'],fixture.name,pages,spool['jobMedia']) is not None,'원래 owned PRINTED/A4portrait/page count 검사 실패')
            used+=len(pdf);require(used<=LIMIT-128*1024,'고정 합성 PDF 전체 상한')
            pdfs.append({'case':case,'path':case+'/printed.pdf','bytes':len(pdf),'sha256':sha,'pages':pages})
            record.update(pdfSha256=sha,pages=pages,inspectionSha256=digest(folder/'pdf-check/inspection.json'),spoolSha256=digest(folder/'spooler.json'))
        case_records.append(record)
    require(len(pdfs)==7 and sum(r['pages'] for r in pdfs)==8,'원래 PDF7개/8페이지 필요')
    report.update(physicalPrintCases=8,ownedSaveCases=7,caseRecords=case_records,pdfs=pdfs,actualGroupboxCaseCount=sum(r['preferencesPath']=='native-groupbox7' for r in case_records),summarySha256=digest(source/'summary.json'),junitSha256=hashlib.sha256(junit).hexdigest(),printCasesPassed=True)
    destination=OUT/'synthetic-pdfs';require(not destination.exists() and not destination.is_symlink(),'기존 PDF 원본 보존')
    stage=Path(tempfile.mkdtemp(prefix='.diagnostic-pdfs-',dir=OUT))
    try:
        for row in pdfs:
            raw=read(source/row['path'],LIMIT);require(hashlib.sha256(raw).hexdigest()==row['sha256'],'복사 직전 PDF 변경')
            target=stage/row['path'];target.parent.mkdir(parents=True)
            with target.open('xb') as stream:stream.write(raw)
        manifest=(json.dumps(report,ensure_ascii=False,indent=2)+'\n').encode('utf8');require(used+len(manifest)<=LIMIT,'manifest 포함8MiB 상한')
        (stage/'diagnostic-manifest.json').write_bytes(manifest);stage.rename(destination)
    finally:
        if stage.exists():shutil.rmtree(stage)

def main():
    global ARCH,ASSETS,EDITOR_SHA,CLI_SHA
    require(sys.argv[1:] in (['--prepare'],['--collect']),'고정 진단 단계만 허용')
    ARCH=os.environ.get('E2E_ARCHITECTURE');require(ARCH in RUNTIMES,'진단 실제아키텍처 미정')
    ASSETS=RUNTIMES[ARCH]['assets'];EDITOR_SHA=RUNTIMES[ARCH]['editorSha256'];CLI_SHA=RUNTIMES[ARCH]['cliSha256']
    scope=bind_diagnostic_context(os.environ);contracts()
    report={'scope':'diagnostic controller uses immutable Source87 binary producer; no Source/Store qualification','controller':scope,'architecture':ARCH,'sourceQualified':False,'wackQualified':False,'storeQualified':False,'printCasesPassed':False,'frozenInputs':INPUTS,'inputBundleSha256':BUNDLE_SHA,'inputOrigin':{'basic2':'Source87 original browser-inputs artifact11767926931 ZIP4467b3b5f2e1daaa9b1c39ec266c119ebbb29512e569349fed71709441488f64','print4':'frozen synthetic generation from actual Source87 WASM ZIP782a8415a442f0a929b6393c0034919a7f6ba5b81f05b278d33b835a0694c7f8; unchanged verifier4 PASS before embedding; no fresh-generation claim'},'contracts':CONTRACTS,'inputGeneration':INPUT_GENERATION}
    OUT.mkdir(exist_ok=True)
    try:
        if sys.argv[1]=='--prepare':
            require(not (OUT/'producer-preparation.json').exists(),'기존 producer 증거 보존')
            work=ROOT/'.work/physical-print';work.mkdir(parents=True,exist_ok=False)
            prepare_runtime(work,report);prepare_inputs()
            from native_architecture import verify_executable
            report['controllerExecutablePE']=verify_executable(Path(sys.executable),'x64')
            report['producer']['inputProvenanceScope']='fixed diagnostic synthetic inputs separately frozen; not a new Source input artifact'
        else:
            prepared=read_json(OUT/'producer-preparation.json')
            require(prepared['controller']==scope and prepared['architecture']==ARCH and prepared['producer']['head']==PRODUCER_HEAD and prepared['producer']['runId']==PRODUCER_RUN,'준비/실행controller와producer 불일치')
            report=prepared;collect(report)
    except BaseException as error:report['errorType']=type(error).__name__[:64];raise
    finally:
        ready=ROOT/'runner-ready/preparation.json'
        if ready.is_file():
            value=read_json(ready);report['osReadiness']={k:value.get(k) for k in ('stage','errorType','hostReadyQualified','inputsPerformed','consentInputsPerformed','registryWrites','processTerminations')};report['osReadiness']['originalSha256']=digest(ready)
        raw=(json.dumps(report,ensure_ascii=False,indent=2)+'\n').encode('utf8');require(len(raw)<=JSON_CAP,'진단 JSON 상한')
        (OUT/('producer-preparation.json' if sys.argv[1]=='--prepare' else 'physical-print-diagnostic.json')).write_bytes(raw)
        print(json.dumps({'printCasesPassed':report['printCasesPassed'],'actualGroupboxCaseCount':report.get('actualGroupboxCaseCount'),'sourceQualified':False,'wackQualified':False,'storeQualified':False}))

if __name__=='__main__':
    sys.path.insert(0,str(ROOT/'scripts'));sys.path.insert(0,str(ROOT/'e2e'));main()
